contract InvMutTest {
    C c;
    constructor() { c = new C(0, "", ""); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(address to, uint256 amount) public payable {
        uint256 ownerBal = c.balanceOf(address(this)); if (__ESBMC_reverted()) return;
        uint256 toBal = c.balanceOf(to); if (__ESBMC_reverted()) return;
        uint256 supplyBefore = c.totalSupply(); if (__ESBMC_reverted()) return;

        require(to != address(0));
        require(amount <= ownerBal);
        require(!c.frozenAccount(address(this)));
        require(!c.frozenAccount(to));

        c.transfer(to, amount); if (__ESBMC_reverted()) return;

        assert(c.balanceOf(address(this)) == ownerBal - amount
            && c.balanceOf(to) == toBal + amount
            && c.totalSupply() == supplyBefore);
    }

    receive() external payable {}
}

